import { Carrera } from './carrera.model';
import { Materia } from './materia.model';
import { RegistroAcademico } from './registro-academico.model';

export class Alumno {
  constructor(
    public legajo: string,
    public nombre: string,
    public promedio: number,
    public carrera: Carrera,
    public registros: RegistroAcademico[],
  ) {}

  getMateriasAprobadas(): Materia[] {
    return this.registros
      .filter(r => r.estaAprobada())
      .map(r => r.getMateria());
  }

  getMateriasDisponibles(): Materia[] {
    const aprobadas = this.getMateriasAprobadas();
    return this.carrera.getPlanEstudio().getMaterias()
      .filter(m => !aprobadas.find(a => a.codigo === m.codigo))
      .filter(m => m.estaDisponible(aprobadas));
  }

  getPorcentajeAvance(): number {
    const total = this.carrera.getTotalMaterias();
    if (total === 0) return 0;
    return Math.round((this.getCantidadAprobadas() / total) * 100);
  }

  getCantidadAprobadas(): number {
    return this.getMateriasAprobadas().length;
  }
}
